import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { BackButton } from '@/components/NavigateButton'
import type { Comment, Post } from '@/types/blog'

type Params = Promise<{ id: string }>

// Replaces `fallback: 'blocking'`: params not returned from
// generateStaticParams are rendered on demand and then cached.
export const dynamicParams = true

// Revalidate the cached post data every 5 minutes
const REVALIDATE_SECONDS = 300

export async function generateStaticParams(): Promise<{ id: string }[]> {
  const posts: Post[] = await fetch(
    'https://jsonplaceholder.typicode.com/posts'
  ).then((res) => res.json())

  return posts.slice(0, 10).map((post) => ({
    id: post.id.toString(),
  }))
}

async function getPost(id: string): Promise<Post | null> {
  const res = await fetch(`https://jsonplaceholder.typicode.com/posts/${id}`, {
    next: { revalidate: REVALIDATE_SECONDS },
  })

  if (!res.ok) {
    return null
  }

  return res.json()
}

async function getComments(id: string): Promise<Comment[]> {
  const res = await fetch(
    `https://jsonplaceholder.typicode.com/posts/${id}/comments`,
    { next: { revalidate: REVALIDATE_SECONDS } }
  )

  if (!res.ok) {
    return []
  }

  return res.json()
}

export async function generateMetadata({
  params,
}: {
  params: Params
}): Promise<Metadata> {
  const { id } = await params
  const post = await getPost(id)

  if (!post) {
    return {}
  }

  const description = post.body.substring(0, 160)

  return {
    title: post.title,
    description,
    openGraph: {
      title: post.title,
      description,
    },
  }
}

export default async function BlogPost({ params }: { params: Params }) {
  const { id } = await params
  const [post, comments] = await Promise.all([getPost(id), getComments(id)])

  if (!post) {
    notFound()
  }

  return (
    <article>
      <BackButton>← Back</BackButton>

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

