import type { NextRequest } from 'next/server'

interface ApiPost {
  id: number
  title: string
  content: string
  createdAt?: string
  updatedAt?: string
}

type UpdatePostBody = Partial<Pick<ApiPost, 'title' | 'content'>>

type RouteContext = { params: Promise<{ id: string }> }

export async function GET(_request: NextRequest, { params }: RouteContext) {
  const { id } = await params

  // Simulate fetching a single post
  const post: ApiPost = {
    id: Number.parseInt(id, 10),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return Response.json(post)
}

export async function PUT(request: NextRequest, { params }: RouteContext) {
  const { id } = await params

  let body: UpdatePostBody = {}
  try {
    body = (await request.json()) as UpdatePostBody
  } catch {
    // Treat a missing or malformed body the same as an empty update
  }

  // Simulate updating a post
  const updatedPost: ApiPost = {
    id: Number.parseInt(id, 10),
    title: body.title || `Post ${id}`,
    content: body.content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return Response.json(updatedPost)
}

export async function DELETE(_request: NextRequest, { params }: RouteContext) {
  const { id } = await params

  // Simulate deleting a post
  return Response.json({ message: `Post ${id} deleted successfully` })
}

